\caption{LABITER: Local algorithm for finding all definite descendants, definite non-descendants and possible descendants of $X$ in $\mathcal{G}^*$.} \SetKwInOut{Input}{Input}
\SetKwInOut{Output}{Output}
\small

\Input{A target $X$, observational data $\mathcal{D}$, background knowledge $\mathcal{B}$.}
\Output{The set of definite descendants, definite non-descendants and possible descendants of $X$ in the MPDAG $\mathcal{G}^*$.}

Learn a local structure $G$ by Algorithm~\ref{alg:mb-by-mb in MPDAG}.

Let $\mathcal{Q}$ be the set of maximal cliques of the induced subgraph of $G$ over $sib(X,G).$

Initialize DefDes, DefNonDes, PosDes $=\emptyset, \emptyset, \emptyset$

\For{$Y \in \mathbf{V}\,\backslash\, \{X\}$} {
\uIf{$X\perp Y | pa(X,G)$}{
Add $Y$ to DefNonDes;
}
\uElseIf{$X \not\perp Y|pa(X,G)\cup sib(X,G)$ or $X\not\perp Y| pa(X,G)\cup \mathbf{Q}$ for every $\mathbf{Q}\in \mathcal{Q}.$}{
Add $Y$ to DefDes;
}
\Else{
Add $Y$ to PosDes;

